/* RiCLite - a small, allocation-free execution framework for statechart code
 * generated by sc2c --style rhapsody.
 *
 * It mirrors the public vocabulary of the Rhapsody C framework (RiCReactive,
 * RiCEvent, RiCTimeout, RiCTask, RiCGEN, IS_IN, RiCSETPARAMS, eventConsumed,
 * Timeout_id ...) so action code written for Rhapsody reads the same, but it
 * is an independent implementation: one task, static pools, no malloc, no
 * recursion, C89-compatible. Suitable for PC simulation and for MCUs.
 *
 * Porting knobs (define before including, or with -D):
 *   RIC_QUEUE_SIZE          event queue depth                       (16)
 *   RIC_EVENT_POOL_SIZE     simultaneously alive user events        (16)
 *   RIC_TIMEOUT_POOL_SIZE   simultaneously armed timeouts           (8)
 *   RIC_MAX_NULL_STEPS      bound on triggerless transition chains  (100)
 *   RIC_CRITICAL_ENTER()    / RIC_CRITICAL_EXIT()  interrupt lock   (empty)
 *   RIC_NO_TRACE            strip state/event trace calls
 *   RIC_NO_STDIO            leave out RiCOXF_printTrace (printf)
 */
#ifndef RICLITE_H
#define RICLITE_H

#include <stddef.h>

#ifndef RIC_QUEUE_SIZE
#define RIC_QUEUE_SIZE 16
#endif
#ifndef RIC_EVENT_POOL_SIZE
#define RIC_EVENT_POOL_SIZE 16
#endif
#ifndef RIC_TIMEOUT_POOL_SIZE
#define RIC_TIMEOUT_POOL_SIZE 8
#endif
#ifndef RIC_MAX_NULL_STEPS
#define RIC_MAX_NULL_STEPS 100
#endif
#ifndef RIC_CRITICAL_ENTER
#define RIC_CRITICAL_ENTER()
#define RIC_CRITICAL_EXIT()
#endif

/* ---- basic types ------------------------------------------------------- */
typedef unsigned char RiCBoolean;
typedef unsigned char RhpBoolean;
typedef int RhpInteger;
typedef unsigned int RhpUnlimitedNatural;
typedef unsigned long RiC_UINT32;
typedef short RiCEventId;
typedef long timeUnit;

#define RiCTRUE  ((RiCBoolean)1)
#define RiCFALSE ((RiCBoolean)0)
#ifndef TRUE
#define TRUE  1
#define FALSE 0
#endif

#define Null_id    ((RiCEventId)-1)
#define Timeout_id ((RiCEventId)-2)
#define RiCNull_id    Null_id
#define RiCTimeout_id Timeout_id

typedef enum RiCTakeEventStatus_t {
    eventNotConsumed = 0,
    eventConsumed = 1
} RiCTakeEventStatus;

struct RiCReactive_t;
struct RiCTask_t;

/* ---- events ------------------------------------------------------------ */
#define RIC_EV_POOLED    0x01u   /* returned to the event pool after dispatch */
#define RIC_EV_CANCELLED 0x02u   /* timeout cancelled while waiting in queue  */

typedef struct RiCEvent_t {
    RiCEventId lId;
    unsigned char flags;
    struct RiCReactive_t *destination;
} RiCEvent;

typedef struct RiCTimeout_t {
    RiCEvent ric_event;               /* lId == Timeout_id                   */
    RiCEventId timeoutId;             /* which tm() of which state          */
    unsigned char state;              /* free / armed / queued              */
    RiC_UINT32 dueTime;
    RiC_UINT32 seq;                   /* start order: breaks ties    */
    const char *msg;
} RiCTimeout;

void RiCEvent_init(RiCEvent *const me, RiCEventId id);
RiCBoolean RiCEvent_isTimeout(const RiCEvent *const me);
RiCEventId RiCTimeout_getTimeoutId(const RiCTimeout *const me);

/* fixed-block pool for user events; generated <Pkg>_Init() registers storage */
void RiCEventPool_register(void *storage, size_t blockSize, unsigned count);
void *RiCEventPool_alloc(void);
void RiCEventPool_free(void *block);

/* ---- reactive objects --------------------------------------------------- */
typedef RiCTakeEventStatus (*RiCDispatchEvent)(void *const, RiCEventId);
typedef void (*RiC_rootState_entDef)(void *const);

typedef struct RiCReactive_Vtbl_t {
    RiCDispatchEvent dispEventFunc;
    RiC_rootState_entDef rootState_entDefFunc;
    const char *className;
} RiCReactive_Vtbl;

#define RIC_R_STARTED    0x01u
#define RIC_R_TERMINATED 0x02u

typedef struct RiCReactive_t {
    const RiCReactive_Vtbl *m_vtbl;
    void *m_owner;
    struct RiCTask_t *myTask;
    RiCEvent *current_event;
    const char *name;
    unsigned char status;
} RiCReactive;

RiCBoolean RiCReactive_init(RiCReactive *const me, void *owner, struct RiCTask_t *task,
                            const RiCReactive_Vtbl *vtbl);
void RiCReactive_cleanup(RiCReactive *const me);
RiCBoolean RiCReactive_startBehavior(RiCReactive *const me);
RiCBoolean RiCReactive_gen(RiCReactive *const me, RiCEvent *event, RiCBoolean fromISR);
/* triggered operation: handle the trigger right now (no queue) and return */
RiCTakeEventStatus RiCReactive_takeTrigger(RiCReactive *const me, RiCEvent *trigger);
void RiCReactive_terminate(RiCReactive *const me);
void RiCReactive_setName(RiCReactive *const me, const char *name);

/* ---- the task: event queue + timer service ------------------------------ */
typedef struct RiCTask_t {
    RiCEvent *queue[RIC_QUEUE_SIZE];
    unsigned head, count;
    RiC_UINT32 now;                   /* ms since RiCOXF_Init              */
} RiCTask;

void RiCTask_schedTm(RiCTask *const me, RiC_UINT32 deltaTime, RiCEventId timeoutId,
                     RiCReactive *const reactive, const char *const msg);
void RiCTask_unschedTm(RiCTask *const me, RiCEventId timeoutId, const RiCReactive *const reactive);

/* ---- application entry points ------------------------------------------- */
void RiCOXF_Init(void);
RiCTask *RiCOXF_mainTask(void);
void RiCOXF_tick(RiC_UINT32 ms);      /* advance time; ISR-safe with locks  */
RiCBoolean RiCOXF_step(void);         /* dispatch one queued event         */
unsigned RiCOXF_processEvents(void);  /* drain the queue, returns # events */
RiC_UINT32 RiCOXF_now(void);
unsigned RiCOXF_pendingEvents(void);

/* errors: pool/queue exhaustion. Default handler does nothing; override.   */
enum { RIC_ERR_EVENT_POOL = 1, RIC_ERR_QUEUE_FULL, RIC_ERR_TIMEOUT_POOL };
extern void (*RiCOXF_errorHook)(int code, const RiCReactive *who);

/* ---- trace -------------------------------------------------------------- */
enum { RIC_TR_ENTER = 0, RIC_TR_EXIT, RIC_TR_EVENT, RIC_TR_DROP, RIC_TR_TRANS };
extern void (*RiCOXF_traceHook)(const RiCReactive *who, int kind, const char *what);
extern const char *(*RiCOXF_eventNameHook)(RiCEventId id);
#ifndef RIC_NO_STDIO
void RiCOXF_printTrace(const RiCReactive *who, int kind, const char *what);
#endif
#ifdef RIC_NO_TRACE
#define RIC_TRACE(r, kind, what) ((void)0)
#else
#define RIC_TRACE(r, kind, what) \
    do { if (RiCOXF_traceHook) RiCOXF_traceHook((r), (kind), (what)); } while (0)
#endif

/* ---- Rhapsody C action-language macros ----------------------------------- */
#define RiCGEN(INSTANCE, EVENT) \
    (((INSTANCE) != NULL) ? \
     RiCReactive_gen(&((INSTANCE)->ric_reactive), (RiCEvent *)RiC_Create_##EVENT, RiCFALSE) : RiCFALSE)
#define CGEN(INSTANCE, EVENT) RiCGEN(INSTANCE, EVENT)
#define GEN(EVENT)            RiCGEN(me, EVENT)
/* send a caller-owned (e.g. static) event object - safe from an ISR */
#define RiCGEN_ISR(INSTANCE, EVENT) \
    RiCReactive_gen(&((INSTANCE)->ric_reactive), (RiCEvent *)(EVENT), RiCTRUE)
#define CGEN_ISR(INSTANCE, EVENT) RiCGEN_ISR(INSTANCE, EVENT)

#define RiCSETPARAMS(me, tType) tType *params = (tType *)((me)->ric_reactive.current_event)
#define CSETPARAMS(me, tType)   RiCSETPARAMS(me, tType)
#define IS_IN(me, sState)       (sState##_IN((me)))

#endif
